const R = $json.valueRanges || [];
const pick = (n) => (R.find(x => String(x.range||'').indexOf(n) === 0) || {}).values || [];
const crit = pick('INVESTOR_CRITERIA');
const inv  = pick('INVESTORS!');
const g = (row,i) => (row && row[i] != null) ? String(row[i]).trim() : '';

// AGNOSTIC only where the firm's own material says sector agnostic
const AGN = { '247':'Alteria - venture debt, self-described sector AND stage agnostic',
              '254':'Golden Gate - no sector mandate; portfolio spans everything',
              '262':'Marwari Catalysts - Tier 2/3 accelerator, no sector mandate stated',
              '267':'RevX - sector-agnostic private debt; revenue is the real constraint' };

// Real codes derived from each firm's stated focus (see findings.md)
const CODES = {
 '252':'FINTECH_CONSUMER, FINTECH_INFRA, FINTECH_SME_LENDING, EDTECH_K12_TESTPREP, EDTECH_UPSKILLING_ENTERPRISE, CLIMATE_ENERGY, AGRITECH, RETAIL_TECH, QUICK_HYPERLOCAL_COMMERCE, SPACETECH, HEALTHTECH_DIGITAL, HEALTHCARE_DELIVERY, D2C_HEALTH_WELLNESS',
 '256':'CONSUMER_TECH_APP, CONSUMER_SERVICES, SAAS_ENTERPRISE, RETAIL_TECH, D2C_HOME_LIFESTYLE, D2C_FASHION_JEWELLERY, D2C_BEAUTY_PERSONAL_CARE, D2C_HEALTH_WELLNESS, AI_APPLIED_ENTERPRISE',
 '258':'AI_FOUNDATIONAL, SEMICONDUCTOR_ELECTRONICS, IOT_SMART_HARDWARE, SPACETECH, DEFENCE_AEROSPACE, BIOTECH_PHARMA, MEDTECH_DEVICES, MANUFACTURING_INDUSTRIAL, DATA_INFRA_DEVTOOLS',
 '259':'SAAS_ENTERPRISE, AI_APPLIED_ENTERPRISE, CONSUMER_TECH_APP, CONSUMER_SERVICES, D2C_HOME_LIFESTYLE, D2C_FASHION_JEWELLERY, D2C_BEAUTY_PERSONAL_CARE, D2C_HEALTH_WELLNESS, SUSTAINABLE_MATERIALS_CIRCULAR, CLIMATE_ENERGY, SPACETECH, FINTECH_CONSUMER',
 '263':'AI_APPLIED_ENTERPRISE, AI_FOUNDATIONAL, SAAS_ENTERPRISE, DATA_INFRA_DEVTOOLS, LOGISTICS_SUPPLY_CHAIN, MANUFACTURING_INDUSTRIAL, CLIMATE_ENERGY, HEALTHTECH_DIGITAL, FINTECH_INFRA',
 '264':'CONSTRUCTION_INFRA_TECH, LOGISTICS_SUPPLY_CHAIN, CLIMATE_ENERGY, EV_CLEAN_MOBILITY, REAL_ESTATE_COWORKING_PROPTECH, HEALTHCARE_DELIVERY, MANUFACTURING_INDUSTRIAL, DATA_INFRA_DEVTOOLS, WATER_TECH',
 '266':'HEALTHCARE_DELIVERY, HEALTHTECH_DIGITAL, CLIMATE_ENERGY, FINTECH_CONSUMER, FINTECH_SME_LENDING, AGRITECH, FNB_PACKAGED_FOOD, CONSUMER_TECH_APP, D2C_HOME_LIFESTYLE, LOGISTICS_SUPPLY_CHAIN, BIOTECH_PHARMA, RETAIL_TECH',
 '268':'AGRITECH, FNB_PACKAGED_FOOD, FNB_FOODSERVICE, HEALTHCARE_DELIVERY, HEALTHTECH_DIGITAL, SAAS_ENTERPRISE, EDTECH_UPSKILLING_ENTERPRISE, TRAVEL_HOSPITALITY, RETAIL_TECH, CONSTRUCTION_INFRA_TECH, MANUFACTURING_INDUSTRIAL, CLIMATE_ENERGY, FINTECH_SME_LENDING',
 '271':'RETAIL_TECH, QUICK_HYPERLOCAL_COMMERCE, SAAS_ENTERPRISE, DATA_INFRA_DEVTOOLS, AGRITECH, CONSUMER_SERVICES, AI_FOUNDATIONAL, SEMICONDUCTOR_ELECTRONICS, IOT_SMART_HARDWARE',
 '273':'RETAIL_TECH, QUICK_HYPERLOCAL_COMMERCE, CONSUMER_TECH_APP, D2C_HOME_LIFESTYLE, D2C_FASHION_JEWELLERY, D2C_BEAUTY_PERSONAL_CARE, D2C_HEALTH_WELLNESS, FINTECH_INFRA, LOGISTICS_SUPPLY_CHAIN'
};

const NOTE = '2026-09-23: activated on Aditya’s instruction. sectors_in derived from the firm’s own stated focus during thesis research; geography mismatch (if noted in thesis_summary) is NOT enforced by the engine, so watch the pass reasons.';

const data = [], done = [], skipped = [];

for (let i = 1; i < crit.length; i++) {
  const c = crit[i];
  const critRow = i + 1;
  const key = g(c,0);
  if (!key) continue;
  const n = parseInt(key,10);
  const ivRow = inv[n-1];
  if (!ivRow || !g(ivRow,0)) continue;
  if (g(ivRow,9)) continue;

  const isTarget = AGN[key] || CODES[key];
  if (!isTarget) continue;

  // only touch rows that currently have NO codes and are not AGNOSTIC
  const mode = g(c,6).toUpperCase();
  if (mode === 'AGNOSTIC' || g(c,7)) { skipped.push(n + ' ' + g(ivRow,0) + ' :: already has codes or is agnostic'); continue; }

  const ch = [];
  if (AGN[key]) { data.push({ range: 'INVESTOR_CRITERIA!G' + critRow, values: [['AGNOSTIC']] }); ch.push('sector_mode LIST->AGNOSTIC'); }
  else { data.push({ range: 'INVESTOR_CRITERIA!H' + critRow, values: [[CODES[key]]] }); ch.push('sectors_in +' + CODES[key].split(',').length + ' codes'); }
  if (g(c,3).toUpperCase() !== 'ACTIVE') { data.push({ range: 'INVESTOR_CRITERIA!D' + critRow, values: [['ACTIVE']] }); ch.push('status->ACTIVE'); }
  if (g(c,4).toUpperCase() === 'PENDING') { data.push({ range: 'INVESTOR_CRITERIA!E' + critRow, values: [['USER']] }); ch.push('confirmed->USER'); }
  if (!g(c,25)) { data.push({ range: 'INVESTOR_CRITERIA!Z' + critRow, values: [[NOTE]] }); ch.push('rule_notes'); }

  done.push({ row: n, investor: g(ivRow,0).slice(0,30), basis: AGN[key] || 'codes from stated focus', changes: ch });
}

if (!data.length) throw new Error('Nothing to do');
if (data.length > 80) throw new Error('Guard: ' + data.length + ' cells exceeds cap 80');

return [{ json: { body: { valueInputOption: 'RAW', data: data }, cells: data.length, rows: done.length, done: done, skipped: skipped } }];
